\begin{align*}
100 &= 2^2 \times 5^2, \\
120 &= 2^3 \times 3 \times 5.
\end{align*}As for the GCD, we take the lowest power of each prime factor, so that is $2^2 \times 5 = 20$ and for the LCM, we take the greatest power of each prime factor, so that is $2^3 \times 3 \times 5^2 = 600$. Therefore, the product of the GCD and LCM is $20 \times 600 = \boxed{12000}.$

Your Answer:
```python
# Let's solve the problem step-by-step using Python to ensure accuracy

# Define the numbers
num1 = 100
num2 = 120

# Find the prime factorization of the numbers
def prime_factors(n):
    i = 2
    factors = {}
    while i * i <= n:
        while (n % i) == 0:
            if i in factors:
                factors[i] += 1
            else:
                factors[i] = 1
            n //= i
        i += 1
    if n > 1:
        factors[n] = 1
    return factors

# Get the prime factors of num1 and num2
factors_num1 = prime_factors(num1)
factors_num2 = prime_factors(num2)

# Calculate the GCD
gcf_factors = {}
for prime in factors_num1:
    if prime in factors_num2:
        gcf_factors[prime] = min(factors_num1[prime], factors_num2[prime])

gcf = 1
for prime in gcf_factors:
    gcf *= prime ** gcf_factors[prime]

# Calculate the LCM
lcm_factors = {}
for prime in factors_num1:
    if prime not in gcf_factors:
        lcm_factors[prime] = factors_num1[prime]
    if prime not in factors_num2:
        lcm_factors[prime] = factors_num2[prime]

lcm = 1
for prime in lcm_factors:
    lcm *= prime ** lcm_factors[prime]

# Calculate the product of the GCD and LCM
product = gcf * lcm

print(product)
